  --panel: #ffffff;
  --border: #d8e1ef;
  --text: #1f2937;
  --muted: #5b6472;
  --highlight: #ffe08a;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 24px;
  background: var(--bg);
  color: var(--text);
  font-family: Arial, Helvetica, sans-serif;
}

.page-header {
  margin-bottom: 20px;
}

.page-header h1 {
  margin: 0 0 8px;
}

.page-header p {
  margin: 0;
  color: var(--muted);
}

.dashboard {
  display: flex;
  gap: 20px;
  align-items: flex-start;
}

.panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 16px;
  box-shadow: 0 10px 30px rgba(15, 23, 42, 0.08);
}

.chart-panel {
  flex: 1 1 62%;
  min-width: 920px;
}

.table-panel {
  flex: 1 1 38%;
  min-width: 450px;
}

.panel-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 18px 20px 0;
}

.legend {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
}

.legend-swatch {
  width: 12px;
  height: 12px;
  border-radius: 50%;
}

.chart-wrapper {
  padding: 10px;
}

#bubble-chart {
  display: block;
  background: linear-gradient(180deg, #f9fbff 0%, #eef4ff 100%);
  border-radius: 14px;
}

.bubble {
  cursor: pointer;
  stroke: #ffffff;
  stroke-width: 2px;
}

.bubble.active {
  stroke: #111827;
  stroke-width: 4px;
}

.bubble-label {
  fill: white;
  font-size: 11px;
  font-weight: bold;
  text-anchor: middle;
  pointer-events: none;
}

.table-wrapper {
  max-height: 760px;
  overflow-y: auto;
  padding: 12px 18px 18px;
}

table {
  width: 100%;
  border-collapse: collapse;
}

thead {
  position: sticky;
  top: 0;
  z-index: 1;
}

th {
  background: #e8eef8;
  padding: 12px;
  text-align: left;
  font-size: 13px;
}

td {
  padding: 11px 12px;
  border-bottom: 1px solid #e7edf7;
  font-size: 13px;
}

tr {
  transition: background-color 0.15s ease;
}

tbody tr:hover,
tr.active {
  background: var(--highlight);
}

.tooltip {
  position: absolute;
  pointer-events: none;
  opacity: 0;
  background: rgba(17, 24, 39, 0.95);
  color: white;
  padding: 10px 12px;
  border-radius: 8px;
  font-size: 12px;
  line-height: 1.5;
  transition: opacity 0.15s ease;
}

.tooltip.visible {
  opacity: 1;
}
