{"command":"create","path":"/root/output/js/visualization.js","file_text":"const width = 900;
const height = 760;
const uniformEtfRadius = 18;

const svg = d3.select('#bubble-chart');
const tooltip = d3.select('#tooltip');
const tableBody = d3.select('#stock-table-body');

const sectors = ['Information Technology', 'Financial', 'Energy', 'Industry', 'ETF'];

const sectorCenters = {
  'Information Technology': { x: width * 0.35, y: height * 0.32 },
  Financial: { x: width * 0.66, y: height * 0.32 },
  Energy: { x: width * 0.32, y: height * 0.7 },
  Industry: { x: width * 0.62, y: height * 0.68 },
  ETF: { x: width * 0.5, y: height * 0.5 }
};

const color = d3
  .scaleOrdinal()
  .domain(sectors)
  .range(['#2563eb', '#059669', '#ea580c', '#7c3aed', '#64748b']);

function formatMarketCap(value) {
  if (!value || Number.isNaN(value)) {
    return 'N/A';
  }

  const abs = Math.abs(value);
  if (abs >= 1e12) {
    return `${(value / 1e12).toFixed(2)}T`;
  }
  if (abs >= 1e9) {
    return `${(value / 1e9).toFixed(2)}B`;
  }
  if (abs >= 1e6) {
    return `${(value / 1e6).toFixed(2)}M`;
  }

  return d3.format(',')(value);
}

function activateSelection(ticker) {
  d3.selectAll('.bubble').classed('active', d => d.ticker === ticker);
  d3.selectAll('tbody tr').classed('active', d => d.ticker === ticker);

  const activeRow = d3.select(`tbody tr[data-ticker="${ticker}"]`).node();
  if (activeRow) {
    activeRow.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  }
}

function buildLegend() {
  const legend = d3.select('#legend');

  sectors.forEach(sector => {
    const item = legend.append('div').attr('class', 'legend-item');

    item
      .append('span')
      .attr('class', 'legend-swatch')
      .style('background-color', color(sector));

    item.append('span').text(sector);
  });
}

function createTable(data) {
  const rows = tableBody
    .selectAll('tr')
    .data(data, d => d.ticker)
    .enter()
    .append('tr')
    .attr('data-ticker', d => d.ticker)
    .on('click', (_, d) => activateSelection(d.ticker));

  rows.append('td').text(d => d.ticker);
  rows.append('td').text(d => d.fullName);
  rows.append('td').text(d => d.sector);
  rows.append('td').text(d => formatMarketCap(d.marketCap));
}

function showTooltip(event, d) {
  if (d.sector === 'ETF') {
    hideTooltip();
    return;
  }

  tooltip
    .classed('visible', true)
    .html(
      `<strong>${d.ticker}</strong><br>` +
        `${d.fullName}<br>` +
        `Sector: ${d.sector}`
    )
    .style('left', `${event.pageX + 12}px`)
    .style('top', `${event.pageY - 20}px`);
}

function hideTooltip() {
  tooltip.classed('visible', false);
}

function createBubbleChart(data) {
  const marketCaps = data.filter(d => d.marketCap).map(d => d.marketCap);

  const radiusScale = d3
    .scaleSqrt()
    .domain([d3.min(marketCaps), d3.max(marketCaps)])
    .range([18, 56]);

  data.forEach(d => {
    d.radius = d.sector === 'ETF' ? uniformEtfRadius : radiusScale(d.marketCap);
  });

  const simulation = d3
    .forceSimulation(data)
    .force('x', d3.forceX(d => sectorCenters[d.sector].x).strength(0.14))
    .force('y', d3.forceY(d => sectorCenters[d.sector].y).strength(0.14))
    .force('center', d3.forceCenter(width / 2, height / 2))
    .force('charge', d3.forceManyBody().strength(3))
    .force('collide', d3.forceCollide(d => d.radius + 3).iterations(2));

  for (let i = 0; i < 300; i += 1) {
    simulation.tick();
  }

  simulation.stop();

  const nodes = svg
    .append('g')
    .selectAll('g')
    .data(data, d => d.ticker)
    .enter()
    .append('g')
    .attr('transform', d => `translate(${d.x},${d.y})`);

  nodes
    .append('circle')
    .attr('class', 'bubble')
    .attr('r', d => d.radius)
    .attr('fill', d => color(d.sector))
    .on('mouseover', showTooltip)
    .on('mousemove', showTooltip)
    .on('mouseout', hideTooltip)
    .on('click', (_, d) => activateSelection(d.ticker));

  nodes
    .append('text')
    .attr('class', 'bubble-label')
    .style('font-size', d => `${Math.min(13, Math.max(9, d.radius / 2.5))}px`)
    .text(d => d.ticker);
}

buildLegend();

d3.csv('data/stock-descriptions.csv').then(rawData => {
  const data = rawData
    .map(row => ({
      ticker: row.ticker.toUpperCase(),
      sector: row.sector,
      fullName: row['full name'],
      marketCap:
        row.marketCap && row.marketCap !== 'nan' ? Number(row.marketCap) : null
    }))
    .sort(
      (a, b) =>
        d3.ascending(a.sector, b.sector) || d3.ascending(a.ticker, b.ticker)
    );

  createBubbleChart(data);
  createTable(data);
});
